// === Tab: mySketch.js ===
//Recycling code here for the Weekly Creative Coding Challenge (#WCCChallenge).
//I did make a few improvements to sequence the folds and show the fold lines!
//Instructions for making this box are here: https://origami.me/box/

let mouse, laggymouse;
let hue, thue;
let lines = false;
let mode = 0;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	mouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	laggymouse = createVector(0, 1.5 * height);
	hue = color(0, 0, 0);
	thue = color(random(155), random(155), random(155), 150);
}

function draw() {
	setScene();
	makeFolds();
	drawPaper();
}

function setScene() {
	mouse.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	mouse.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	laggymouse.lerp(mouse, 0.02);
	let x = map(laggymouse.y, 0, height, PI, -PI);
	let z = map(laggymouse.x, 0, width, HALF_PI, -HALF_PI);
	rotateX(x + QUARTER_PI);
	rotateZ(z);
	let zoom = map(laggymouse.y, 0, height, 3 * height / 566, 0.5 * height / 566);
	scale(zoom);
	hue = lerpColor(hue, thue, 0.05);
	if (mode == 0) background(hue);
	else background(0);
	ambientLight(100);
	pointLight(150, 150, 150, width, -height, -height / 2);
	if (lines) stroke(255, 150);
	else noStroke();
	specularMaterial(hue);
}

function makeFolds() {
	fold1 = map(laggymouse.x, width / 8, 3 * width / 8, 0, -PI + 0.02, true);
	fold2 = map(laggymouse.x, 3 * width / 8, width / 2, 0, -PI + 0.02, true);
	fold3 = map(laggymouse.x, width / 2, 5 * width / 8, 0, -PI + 0.02, true);
	fold4 = map(laggymouse.x, 5 * width / 8, 3 * width / 4, 0, -PI + 0.02, true);
	fold5 = map(laggymouse.x, 3 * width / 4, 7 * width / 8, 0, -PI + 0.02, true);
}

function drawPaper() {
	drawBase();
	for (let ang = 0; ang < TWO_PI; ang += HALF_PI) {
		push();
		rotateZ(ang);
		foldSides(ang);
		pop();
	}
}

function drawBase() {
	push(); //base square
	beginShape();
	vertex(-50, -50, 0);
	vertex(-50, 50, 0);
	vertex(50, 50, 0);
	vertex(50, -50, 0);
	endShape();
	pop();
}

function foldSides(ang) {
	push(); //center strip
	translate(50, 0, 0);
	rotateY(fold1 / 2);
	beginShape();
	vertex(50, -50, 0);
	vertex(50, 50, 0);
	vertex(0, 50, 0);
	vertex(0, -50, 0);
	endShape();

	push(); //bottom triangle
	translate(0, -50, 0);
	rotateX(fold1);
	beginShape();
	vertex(50, 0, 0);
	vertex(0, 0, 0);
	vertex(50, -50, 0);
	endShape();
	pop();

	push(); //top triangle
	translate(0, 50, 0);
	rotateX(-fold1);
	beginShape();
	vertex(50, 0, 0);
	vertex(0, 0, 0);
	vertex(50, 50, 0);
	endShape();
	pop();

	push(); //midsection
	translate(50, 0, 0);
	if (ang == 0) rotateY(fold2);
	else if (ang == HALF_PI) rotateY(fold3);
	else if (ang == PI) rotateY(fold4);
	else rotateY(fold5);

	beginShape(); //center rectangle
	vertex(0, -50, 0);
	vertex(50, -50, 0);
	vertex(50, 50, 0);
	vertex(0, 50, 0);
	endShape();

	push(); //bottom triangle
	translate(0, 50, 0);
	rotateX(-fold1); //!!
	beginShape();
	vertex(0, 0, 0);
	vertex(50, 0, 0);
	vertex(0, 50, 0);
	endShape();
	pop();

	push(); //top triangle
	translate(0, -50, 0);
	rotateX(fold1);
	beginShape();
	vertex(0, 0, 0);
	vertex(50, 0, 0);
	vertex(0, -50, 0);
	endShape();
	pop();

	push(); //outer tip
	translate(50, 0, 0);
	rotateY(-fold1 / 2);
	beginShape();
	vertex(0, -50, 0);
	vertex(50, 0, 0);
	vertex(0, 50, 0);
	endShape();
	pop();
	pop();
	pop();
}

function mousePressed() {
	thue = color(random(155), random(155), random(155), 150);
}

function keyPressed() {
	if (keyCode == 32) lines = !lines;
	if (key == 'm') mode = 1 - mode;
}
